using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.Linq;
using System.IO;
using ConRoi.Investigation.V36;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (EditorApplication.isPlaying)
                throw new System.Exception("Edit required");
            var scene = EditorSceneManager.GetActiveScene();
            if (!scene.path.EndsWith("r102.unity"))
                throw new System.Exception("r102 only");
            var all = scene.GetRootGameObjects().SelectMany(g => g.GetComponentsInChildren<Transform>(true)).ToArray();
            var roots = all.Where(t => t.name.StartsWith("ConRoi_Minh_") || t.name == "Desk_Puppet_Broken_Strings").ToArray();
            string removed = string.Join("\n", roots.Select(t => t.name));
            foreach (var t in roots)
                if (t)
                    Object.DestroyImmediate(t.gameObject);
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            scene = EditorSceneManager.OpenScene(scene.path);
            all = scene.GetRootGameObjects().SelectMany(g => g.GetComponentsInChildren<Transform>(true)).ToArray();
            int missing = all.Sum(t => GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));
            int oldHeads = all.Count(t => t.name == "ConRoi_Head_SameAsMinh");
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            string text = "Scene=" + scene.path + " dirty=" + scene.isDirty + " missing=" + missing + " oldHeads=" + oldHeads + "\nRemoved scene-only roots:\n" + removed + "\n";
            foreach (var mb in all.SelectMany(t => t.GetComponents<MonoBehaviour>()).Where(m => m && m.GetType().Assembly == typeof(InvestigationSession).Assembly))
                if (mb != s.movement && mb != s.look && !mb.GetType().Namespace.StartsWith("ConRoi.Investigation.V36"))
                    throw new System.Exception("Legacy script remains: " + mb.GetType().Name);
            if (missing != 0 || oldHeads != 0)
                throw new System.Exception(text);
            if (!s.clipCamera || !s.cipherPuppet || s.poseIcons.Any(p => !p))
                throw new System.Exception("Prototype reference missing");
            File.WriteAllText("Test/KetQua/investigation_r102/final-reopen-before-play.txt", text);
            EditorApplication.isPlaying = true;
            r.Log(text + "Entering final scoped Play from normal authored start. No save loaded.");
        }
    }
}

